mapper.select:
select id, title, week_number, sessions_per_week, description from training_plans where active = true
and id = #{planId}
order by sort_order, id limit 1

select pi.id, pi.day_offset, pi.course_id, c.title course_title, c.duration_minutes,
       case when exists (
           select 1 from workout_records wr
           where wr.user_id = #{userId} and wr.course_id = pi.course_id
             and wr.completed_at >= #{weekStart} and wr.completed_at < #{weekEnd}
       ) then 'COMPLETED' else 'PENDING' end item_status
from training_plan_items pi
join courses c on c.id = pi.course_id
where pi.plan_id = #{planId}
order by pi.day_offset, pi.sort_order

mapper.update:
update user_plan_selections
set plan_id = #{planId}, selected_at = current_timestamp
where user_id = #{userId}
